(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.012+t*0.2)*20 + Math.cos(y*0.015-t*0.15)*15 + Math.sin((x+y)*0.008+t*0.1)*10;
  const w1y = Math.cos(y*0.013-t*0.18)*20 + Math.sin(x*0.016+t*0.22)*15 + Math.cos((x-y)*0.009-t*0.12)*10;
  const wx = x + w1x + Math.sin(w1y*0.03+t*0.3)*8;
  const wy = y + w1y + Math.cos(w1x*0.03-t*0.25)*8;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.07,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.055,2.3,2.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.065,2.6,3.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.08,1.9,1.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.13,1.3,2.2],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*70,0.075,2.1,0.5],
    [200+Math.sin(t*0.38+6)*110,220+Math.cos(t*0.48+2)*60,0.095,1.8,3.8],
    [300+Math.cos(t*0.42+1)*90,30+Math.sin(t*0.58+3)*40,0.085,2.4,1.0]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    mS+=Math.sin(d*f*0.5-t*sp*0.3+ph*2.0);
  }
  const n=src.length,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(wx*0.035+wy*0.022+t*0.7)+Math.sin(wx*0.028-wy*0.038+t*1.0)+Math.sin((wx+wy)*0.1+t*2.2)*0.4+Math.sin((wx-wy)*0.08-t*1.8)*0.4+Math.sin(wx*0.05+t*1.5)*0.3)/2.8;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.06-ang*2+t*0.8)*0.5)*0.3;
  let minD=999,minD2=999;
  for(let i=0;i<6;i++){
    const gx=(i*83+Math.sin(t*0.3+i)*40+100)%480;
    const gy=(i*47+Math.cos(t*0.25+i*1.5)*30+60)%240;
    const d=Math.sqrt((wx-gx)**2+(wy-gy)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2){minD2=d;}
  }
  const cell=Math.tanh((minD2-minD)*0.08-0.5)*0.4;
  const raw=act-inh*0.65+bg*0.25+spiral*0.35+mod*0.2+cell*0.15;
  const reaction=Math.tanh(raw*2.0);
  const fine=Math.sin(wx*0.2+Math.sin(wy*0.15+t)*2)*Math.sin(wy*0.18+Math.sin(wx*0.12-t*0.7)*2)*0.15;
  const blend=reaction*0.8+fine*0.2,v=blend*0.5+0.5;
  const pal=[[12,15,52],[18,55,98],[20,110,120],[35,165,145],[180,185,70],[215,170,50],[220,120,55],[195,70,60],[150,40,65],[85,25,75],[40,18,60],[12,15,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(reaction)*0.1;
  const edgeGlow=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*0.8:1.0;
  const vignette=1.0-Math.pow(dist/280,2)*0.25;
  const m=lum*edgeGlow*vignette;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*m)|0];
}
